const tabId = 248688717;

const pageData = await browserjs(tabId, () => {
  // Let's find the results count element
  const countEl = document.querySelector('[class*="pet-count"], [class*="results-count"], [role="status"]');

  // Find all pet cards
  // Petfinder usually has pet cards with articles or specific card structures
  const cards = [];
  const cardElements = document.querySelectorAll('article, [data-test="pet-card"], [class*="PetCard"], [class*="pet-card"]');

  // If cardElements is empty, let's find links to /details/
  const detailLinks = Array.from(document.querySelectorAll('a[href*="/details/"]'));
  const seenUrls = new Set();

  const pets = [];
  for (const link of detailLinks) {
    if (seenUrls.has(link.href)) continue;
    seenUrls.add(link.href);

    // Find ancestor card
    let parent = link.parentElement;
    for (let i = 0; i < 6 && parent; i++) {
      if (parent.querySelector('img') && parent.innerText.includes('miles away')) {
        break;
      }
      parent = parent.parentElement;
    }

    const text = parent ? parent.innerText : link.innerText;
    pets.push({
      url: link.href,
      fullText: text
    });
  }

  // Also check pagination
  const pagination = document.querySelector('[aria-label="Pagination"], [class*="pagination"], [class*="Pagination"]')?.innerText;

  // Total results text
  const statusTexts = Array.from(document.querySelectorAll('status, [role="status"], h1, h2, h3')).map(e => e.innerText.trim()).filter(Boolean);

  return {
    statusTexts: statusTexts.slice(0, 10),
    pagination,
    petCount: pets.length,
    pets: pets
  };
});

