const cats = await browserjs(tabId, () => {
  // Let's find all pet cards on the page
  // Inspect the structure of a pet card
  const results = [];

  // Look at images with alt text or card elements
  const imgs = Array.from(document.querySelectorAll('img[alt*="ADOPTABLE"]'));
  for (const img of imgs) {
    // The alt text is like: "Moxie, ADOPTABLE, Adult • Female, Domestic Short Hair."
    const alt = img.getAttribute('alt') || '';

    // Find the surrounding card or container
    let el = img;
    while (el && !el.innerText?.includes('miles away') && el !== document.body) {
      el = el.parentElement;
    }

    const cardText = el ? el.innerText : '';
    const link = el ? el.querySelector('a[href*="/cat/"]') : null;

    results.push({
      alt,
      url: link ? link.href : null,
      cardText: cardText.split('\n').map(s => s.trim()).filter(Boolean)
    });
  }

  return results;
});

