const tabId = 248688717;

const fullCardData = await browserjs(tabId, () => {
  // Let's find all cards in the pet search grid
  const detailLinks = Array.from(document.querySelectorAll('a[href*="/cat/"][href*="/details/"]'));
  const uniqueHrefs = Array.from(new Set(detailLinks.map(a => a.href)));

  return uniqueHrefs.map(href => {
    const linkEl = document.querySelector(`a[href="${href}"]`);
    // Traverse up to find the card root
    let card = linkEl;
    while (card && card.parentElement && !card.innerText.includes("VIEW PROFILE") && !card.innerText.includes("miles away")) {
      card = card.parentElement;
    }
    // card could be the parent of VIEW PROFILE
    while (card && card.parentElement && card.parentElement.innerText.includes(card.innerText)) {
      if (card.parentElement.querySelectorAll('a[href*="/details/"]').length > 1) {
        break; // don't go past the container of multiple cards
      }
      card = card.parentElement;
    }

    const img = card?.querySelector('img[alt]');
    const alt = img ? img.getAttribute('alt') : '';

    return {
      href,
      text: card?.innerText?.split('\n').map(s => s.trim()).filter(Boolean),
      alt
    };
  });
});

