const tabId = 248688717;

const catDetails = await browserjs(tabId, () => {
  // Let's inspect the cards
  const links = Array.from(document.querySelectorAll('a[href*="/cat/"][href*="/details/"]'));
  const uniqueHrefs = Array.from(new Set(links.map(a => a.href)));

  return uniqueHrefs.map(href => {
    // Find all links matching this href
    const matchingLinks = Array.from(document.querySelectorAll(`a[href="${href}"]`));
    // Find images inside or nearby
    let alt = "";
    for (const l of matchingLinks) {
      const img = l.querySelector('img');
      if (img && img.alt) {
        alt = img.alt;
        break;
      }
    }
    if (!alt) {
      // search in card container
      const card = matchingLinks[0]?.closest('div[class*="Card"], article, li') || matchingLinks[0]?.parentElement?.parentElement;
      const img = card?.querySelector('img');
      if (img && img.alt) alt = img.alt;
    }

    // Also let's get text content of the card
    const cardEl = matchingLinks[0]?.closest('div[class*="Card"], article, li') || matchingLinks[0]?.parentElement?.parentElement?.parentElement;

    return {
      href,
      alt,
      inner: cardEl?.innerText
    };
  });
});

