const pets = await browserjs(tabId, () => {
  const cards = Array.from(document.querySelectorAll('.PFPetDetailCard_flipInner__LhPfg, [class*="PFPetDetailCard_flipInner"]'));

  return cards.map(card => {
    const link = card.querySelector('a[href*="/cat/"][href*="/details/"]');
    const img = card.querySelector('img[alt]');
    const nameEl = card.querySelector('.tw-font-extrabold, [class*="tw-font-extrabold"]');
    const distanceEl = card.querySelector('.tw-text-xs, [class*="tw-text-xs"]');

    // Find age/gender and breed spans
    const spans = Array.from(card.querySelectorAll('.tw-text-primary-600 span, [class*="tw-text-primary-600"] span'))
      .map(s => s.textContent.trim())
      .filter(s => s.length > 0);

    // Extract info from URL as well
    // URL format: /cat/<slug>-<uuid>/ca/<city>/<shelter-slug>/details/
    const url = link ? link.href : '';
    const urlMatch = url.match(/\/cat\/([^/]+)\/ca\/([^/]+)\/([^/]+)\//);
    const city = urlMatch ? urlMatch[2].replace(/-/g, ' ') : '';
    const shelter = urlMatch ? urlMatch[3].replace(/-/g, ' ') : '';

    return {
      name: nameEl ? nameEl.textContent.trim() : (img?.alt?.split(',')[0] || ''),
      distance: distanceEl ? distanceEl.textContent.trim() : '',
      ageGender: spans[0] || '',
      breed: spans[1] || (img?.alt?.split(',').pop()?.trim() || ''),
      city: city.charAt(0).toUpperCase() + city.slice(1),
      shelter: shelter,
      url: url,
      imageAlt: img ? img.alt : ''
    };
  });
});

